import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";

const WorkerSplash = ({ onComplete }) => {
  const [isImploding, setIsImploding] = useState(false);
  const [glitch, setGlitch] = useState(false);

  useEffect(() => {
    const glitchInterval = setInterval(() => setGlitch(prev => !prev), 150);
    const transitionTimer = setTimeout(() => setIsImploding(true), 3000);
    const completeTimer = setTimeout(onComplete, 3700);

    return () => { 
      clearInterval(glitchInterval);
      clearTimeout(transitionTimer); 
      clearTimeout(completeTimer); 
    };
  }, [onComplete]);

  return (
    <div className="h-screen w-full bg-[#030303] flex items-center justify-center overflow-hidden font-mono">

      {/* 1. LAYER ONE: Top Terminal Data (Subtle) */}
      <div className="absolute top-10 left-10 opacity-20 text-[#CAD23C] text-[8px] font-bold leading-none select-none">
        <p>IP_TRACE: 192.168.1.104</p>
        <p>NODE_STATUS: ACTIVE</p>
        <p>ENCRYPTION: AES_256</p>
      </div>

      <div className={`${isImploding ? "animate-void" : ""}`}>
        <div className="flex flex-col items-center">

          <div className="flex gap-2 text-white font-[1000] text-7xl md:text-9xl tracking-tight italic">
            <motion.span 
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.1, delay: 0.8 }}
              className={glitch ? "glitch-active" : ""}
            >
              T
            </motion.span>

            <motion.span 
              initial={{ opacity: 0, scale: 0 }}
              animate={{ opacity: 1, scale: 1 }}
              transition={{ type: "spring", stiffness: 500, delay: 1.2 }}
              className="text-[#CAD23C] drop-shadow-[0_0_15px_rgba(202,210,60,0.5)]"
            >
              2
            </motion.span>

            <motion.span 
              initial={{ opacity: 0, x: 20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.1, delay: 1.0 }}
            >
              T
            </motion.span>
          </div>

          <div className="mt-8 flex flex-col items-center">
             <motion.div 
               initial={{ width: 0 }} animate={{ width: "240px" }}
               transition={{ duration: 2, delay: 1.2 }}
               className="h-[1px] bg-gradient-to-r from-transparent via-[#CAD23C] to-transparent"
             />
             <div className="mt-2 text-[9px] text-[#CAD23C] tracking-[1.5em] font-black uppercase">
                {glitch ? "INITIALIZING_SYSTEM" : "ACCESS_GRANTED"}
             </div>
          </div>
        </div>
      </div>

      {/* 2. OVERLAY: CRT Scanlines */}
      <div className="absolute inset-0 pointer-events-none z-50 bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.1)_50%)] bg-[length:100%_4px]" />
    </div>
  );
};

export default WorkerSplash;
